//! A press in a text field: where it puts the caret, what a double or triple click selects, and
//! how dragging pulls a selection out.
//!
//! The field's text is generated by layout, so the point's byte comes from the field position
//! provider ([`Document::set_field_position_provider`]). Observed in Electron 39.8.10 (a hidden
//! window, `sendInputEvent` mouse events; probe `p32c/click`): a click puts the caret at the
//! nearest character boundary, past the end of a line at its end, below the last line at the end
//! of the text; Shift extends from the old anchor; a double click selects the word under the
//! pointer and, for a word, the spaces and tabs after it (`world  ` of `world  foo`, but `foo` of
//! `foo-bar` and not the `-`), a lone punctuation mark with the spaces after it (`, `), a run of
//! spaces by itself, and a line break by itself; a triple click selects a whole input and the
//! line of a `<textarea>`.

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

use crate::bind;
use crate::dom::NodeId;
use crate::field::Draft;
use crate::{Document, Pointer};

impl Document {
    /// The text field a press on `target` is in, if it is one that a caret can stand in.
    fn field_pressed(&self, target: NodeId) -> Option<NodeId> {
        let state = self.state.borrow();
        let dom = &state.dom;
        let mut at = Some(target);
        while let Some(node) = at {
            let found = dom.get(node)?;
            if matches!(found.tag(), Some("input" | "textarea")) {
                let live = found.draft.is_some() && found.attr("disabled").is_none();
                return live.then_some(node);
            }
            at = dom.parent(node);
        }
        None
    }

    /// A fingerprint of the text, caret and anchor of the text field with the focus, and which
    /// field it is: the same before and after a message that moved nothing in it. The shell of
    /// a page scrolls the caret into view only when this changed, as Chromium does (Electron
    /// 39.8.10, `p32c-review/fld-out.json`: a textarea scrolled away from its caret stays so
    /// through mouse moves, a lone Shift and Ctrl+C, and only typing or the arrows reveal it).
    pub fn field_mark(&self) -> Option<(NodeId, u64)> {
        let state = self.state.borrow();
        let node = state.dom.focused?;
        let draft = state.dom.get(node)?.draft.as_ref()?;
        let mut hasher = DefaultHasher::new();
        draft.text().hash(&mut hasher);
        (draft.caret(), draft.selection(), draft.marked()).hash(&mut hasher);
        Some((node, hasher.finish()))
    }

    /// The primary button went down at `pointer` on a text field: the caret goes there, or the
    /// word or line there is selected. Answers whether it was a field that did so; without a
    /// field position provider it is left to the old rule (the field keeps its selection).
    pub(crate) fn press_in_field(
        &self,
        runtime: &mut verve::Runtime,
        target: NodeId,
        pointer: &Pointer,
    ) -> bool {
        let Some(field) = self.field_pressed(target) else {
            return false;
        };
        let Some((near, under)) = self.field_offset_at(field, pointer.x, pointer.y) else {
            return false;
        };
        let count = pointer.count;
        let shift = pointer.modifiers.shift;
        let words = select_in(runtime, field, |draft, multiline| match count {
            0 | 1 if shift => draft.extend_to(near),
            0 | 1 => draft.place(near),
            2 => draft.select_word_around(under),
            _ if multiline => draft.select_line_at(near),
            _ => {
                draft.select_all();
            }
        });
        let words = (count == 2).then(|| words.word_span(under));
        {
            let mut view = self.view.borrow_mut();
            view.drag.field = Some(field);
            view.drag.words = words;
        }
        // The page's own selection leaves the text it was on: a caret before the field, as in
        // Chromium (Electron 39.8.10, `p32c-review/fld-out.json`).
        bind::node::with_dom(runtime.context(), |dom| {
            if let Some(parent) = dom.parent(field) {
                let at = dom.children(parent).iter().position(|c| *c == field);
                dom.select_between((parent, at.unwrap_or(0)), (parent, at.unwrap_or(0)));
            }
        });
        true
    }

    /// The pointer moved with the button down in a field: the selection reaches to it, wherever
    /// it is.
    pub(crate) fn drag_in_field(&self, runtime: &mut verve::Runtime, pointer: &Pointer) -> bool {
        let Some(field) = self.view.borrow().drag.field else {
            return false;
        };
        if pointer.buttons & 1 == 0 {
            self.view.borrow_mut().drag.field = None;
            return false;
        }
        if let Some((near, under)) = self.field_offset_at(field, pointer.x, pointer.y) {
            // After a double click the selection grows by whole words.
            let words = self.view.borrow().drag.words.clone();
            select_in(runtime, field, |draft, _| match &words {
                Some(base) => draft.extend_by_words(base, under),
                None => draft.extend_to(near),
            });
        }
        true
    }
}

/// Changes the draft of `field` and has the document show it. Answers the draft as it is then.
fn select_in(
    runtime: &mut verve::Runtime,
    field: NodeId,
    change: impl FnOnce(&mut Draft, bool),
) -> Draft {
    bind::node::with_dom(runtime.context(), |dom| {
        bind::element::ensure_draft(dom, field);
        let multiline = dom.get(field).and_then(|n| n.tag()) == Some("textarea");
        let mut shown = Draft::default();
        if let Some(draft) = dom.get_mut(field).and_then(|n| n.draft.as_mut()) {
            change(draft, multiline);
            shown = draft.clone();
            dom.mark(field);
        }
        shown
    })
}
